-- Rivals Coach — illustrations des guides : bucket d'images, schémas tactiques et combos.
-- À exécuter après 0009_hero_guides.sql. Ré-exécutable sans risque.

-- Bucket public en lecture (icônes de capacités, captures), écriture réservée aux admins
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('guide-images', 'guide-images', true, 5242880, array['image/png', 'image/jpeg', 'image/webp', 'image/gif'])
on conflict (id) do nothing;

drop policy if exists "guide_images_admin_select" on storage.objects;
drop policy if exists "guide_images_admin_insert" on storage.objects;
drop policy if exists "guide_images_admin_update" on storage.objects;
drop policy if exists "guide_images_admin_delete" on storage.objects;
create policy "guide_images_admin_select" on storage.objects for select to authenticated
  using (bucket_id = 'guide-images' and public.is_admin());
create policy "guide_images_admin_insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'guide-images' and public.is_admin());
create policy "guide_images_admin_update" on storage.objects for update to authenticated
  using (bucket_id = 'guide-images' and public.is_admin())
  with check (bucket_id = 'guide-images' and public.is_admin());
create policy "guide_images_admin_delete" on storage.objects for delete to authenticated
  using (bucket_id = 'guide-images' and public.is_admin());

-- Schéma tactique sur la section « Philosophie de jeu » (la première) de chaque guide
update public.guides g set content = jsonb_set(g.content, '{sections,0,diagram}', to_jsonb('angle'::text)) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'adam-warlock' and jsonb_typeof(g.content->'sections') = 'array' and jsonb_array_length(g.content->'sections') > 0;
