-- Combos en touches (repris du texte des guides)
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo rapproché", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Clic D", "label": "tir chargé"}, {"key": "Clic G", "label": "tir"}], "note": "Bien placé, il élimine une cible fragile."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'adam-warlock';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo de base", "steps": [{"key": "Mêlée", "label": ""}, {"key": "", "label": "Coup de lance"}, {"key": "Clic D", "label": "bouclier"}], "note": "Lever le bouclier après le combo **regagne de la jauge**."}, {"title": "Recharger la jauge", "steps": [{"key": "", "label": "Coup de lance"}, {"key": "Maj", "label": "charge"}, {"key": "", "label": "Coup de lance"}], "note": "Porter une cible recharge vite ta jauge de dégâts."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'angela';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "De base", "steps": [{"key": "", "label": "Lance"}, {"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "Maj", "label": "dash"}], "note": "Rapide, mais juste contre un support qui reçoit des soins."}, {"title": "Plus de dégâts", "steps": [{"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "Maj", "label": "dash"}], "note": "Idéal en prolongation, quand les soins manquent."}, {"title": "Variante courante", "steps": [{"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Coup de pied"}, {"key": "Maj", "label": "dash"}], "note": ""}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'black-panther';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Mise à mort sûre", "steps": [{"key": "Clic G", "label": "tir au corps"}, {"key": "E", "label": "coup de pied"}, {"key": "Clic G", "label": "tir au corps"}], "note": "Sur une cible fragile, **pas besoin de headshot**."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'black-widow';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo de base", "steps": [{"key": "", "label": "Tir"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Tir"}], "note": "Le dash au fusil applique l'**anti-soin** entre deux tirs."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'blade';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo complet", "steps": [{"key": "Maj", "label": "sprint"}, {"key": "Espace", "label": "saut"}, {"key": "E", "label": "lancer bouclier"}, {"key": "", "label": "Écrasement"}, {"key": "F", "label": "charge"}, {"key": "Clic G", "label": "coups"}], "note": "Attends le **son d'impact** du bouclier avant d'enchaîner, sinon tu annules ton attaque."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'captain-america';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo principal", "steps": [{"key": "F", "label": "marque"}, {"key": "", "label": "Lancer"}, {"key": "F", "label": "dash"}, {"key": "", "label": "Attaque bondissante"}, {"key": "", "label": "Frappe au sol"}, {"key": "", "label": "Attaque bondissante"}], "note": "Le lancer ricoche et ralentit : c'est ton ouvreur de loin."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'daredevil';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Éliminer un fragile", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Mêlée", "label": ""}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Explosion des ténèbres"}], "note": "Avec **au moins la moitié de la jauge**."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'doctor-strange';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo de base", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "E", "label": "charge"}, {"key": "Clic G", "label": "tir"}, {"key": "E", "label": "détonation"}, {"key": "Clic G", "label": "tir"}], "note": "Garde assez de munitions pour le lancer en entier."}, {"title": "Avec la balle vivante", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "E", "label": "charge"}, {"key": "Clic D", "label": "balle vivante"}, {"key": "Clic G", "label": "tir"}], "note": "Élimine une cible et te laisse ta fuite."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'elsa-bloodstone';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo de base", "steps": [{"key": "Maj", "label": "forme diamant"}, {"key": "", "label": "Étranglement"}, {"key": "", "label": "Coup"}, {"key": "", "label": "Coup"}, {"key": "", "label": "Coup de pied au mur"}], "note": "Ajoute un coup de plus pour plus de sécurité."}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'emma-frost';
update public.guides g set content = g.content || jsonb_build_object('combos', $c$[{"title": "Combo pick", "steps": [{"key": "", "label": "Paquet dégâts"}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Dash renforcé"}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Carte anti-soin"}], "note": ""}]$c$::jsonb) from public.heroes h where g.kind = 'hero' and g.hero_id = h.id and h.slug = 'gambit';
